// Static — poore section ka default
export const metadata = {
  title: 'Mera Blog',
  description: 'Web dev seekhne ki jagah',
};

// Dynamic — har post ka apna title
export async function generateMetadata({ params }) {
  const { slug } = await params;
  const post = await getPost(slug);
  return {
    title: post.title,
    openGraph: {
      images: [post.coverUrl],   // WhatsApp preview
    },
  };
}

// Title template — sections mein "%s | Mera Blog"
export const metadata = {
  title: { default: 'Mera Blog', template: '%s | Mera Blog' },
};

